#!/usr/bin/env bash
set -euo pipefail
python3 - "$@" <<'PY'
import csv,json,re,sys
from pathlib import Path
state,report=map(Path,sys.argv[1:3]);rows=[]
for name in sys.argv[3:]:
    with open(name,newline='') as f:
        reader=csv.reader(f,delimiter='\t',quoting=csv.QUOTE_NONE)
        if next(reader,None)!=['event_id','service','result']:sys.exit(2)
        for cells in reader:
            if len(cells)!=3 or any(re.fullmatch(r'[A-Za-z0-9-]+',v) is None for v in cells[:2]) or cells[2] not in ('ok','fail'):sys.exit(2)
            rows.append(dict(zip(['event_id','service','result'],cells)))
stored=json.loads(state.read_text()) if state.exists() else {'seen':[],'counts':{}}
seen=set(stored['seen']);counts=stored['counts']
for r in rows:
    if r['event_id'] in seen:continue
    seen.add(r['event_id']);v=counts.setdefault(r['service'],{'ok':0,'fail':0});v[r['result']]+=1
nextstate={'seen':sorted(seen),'counts':counts}
text='service\tok\tfail\n'+''.join(f"{s}\t{v['ok']}\t{v['fail']}\n" for s,v in sorted(counts.items()))
state.parent.mkdir(parents=True,exist_ok=True);report.parent.mkdir(parents=True,exist_ok=True)
state.write_text(json.dumps(nextstate,sort_keys=True)+'\n');report.write_text(text)
PY
